import java.util.*;

public class Main {
    class LFUCache {
        int capacity;
        int clock = 0;
        Map<Integer, int[]> cache = new HashMap<>();                       // key to [value, frequency, lastUsedTime]

        public LFUCache(int capacity) {
            this.capacity = capacity;
        }

        void touch(int key) {
            clock++;
            cache.get(key)[1]++;
            cache.get(key)[2] = clock;
        }

        public int get(int key) {
            if (!cache.containsKey(key)) return -1;
            touch(key);
            return cache.get(key)[0];
        }

        public void put(int key, int value) {
            if (capacity == 0) return;
            if (cache.containsKey(key)) {
                cache.get(key)[0] = value;
                touch(key);
                return;
            }
            if (cache.size() >= capacity) {
                int evictKey = -1, bestFreq = Integer.MAX_VALUE, bestTime = Integer.MAX_VALUE;
                for (Map.Entry<Integer, int[]> entry : cache.entrySet()) {         // scans everything
                    int[] v = entry.getValue();
                    if (v[1] < bestFreq || (v[1] == bestFreq && v[2] < bestTime)) {
                        bestFreq = v[1]; bestTime = v[2]; evictKey = entry.getKey();
                    }
                }
                cache.remove(evictKey);
            }
            clock++;
            cache.put(key, new int[]{value, 1, clock});
        }
    }

    public static void main(String[] args) {
        LFUCache cache = new LFUCache(2);
        cache.put(1, 1);
        cache.put(2, 2);
        System.out.println(cache.get(1));
        cache.put(3, 3);
        System.out.println(cache.get(2));
        System.out.println(cache.get(3));
        cache.put(4, 4);
    }
}

