using namespace std;

class LFUCache {
public:
    int capacity, clock = 0;
    unordered_map<int, array<int, 3>> cache;                              // key to {value, frequency, lastUsedTime}

    LFUCache(int capacity) : capacity(capacity) {}

    void touchKey(int key) {
        clock++;
        cache[key][1]++;
        cache[key][2] = clock;
    }

    int get(int key) {
        if (!cache.count(key)) return -1;
        touchKey(key);
        return cache[key][0];
    }

    void put(int key, int value) {
        if (capacity == 0) return;
        if (cache.count(key)) {
            cache[key][0] = value;
            touchKey(key);
            return;
        }
        if ((int)cache.size() >= capacity) {
            int evictKey = -1, bestFreq = INT_MAX, bestTime = INT_MAX;
            for (auto& entry : cache) {                                          // scans everything
                if (entry.second[1] < bestFreq || (entry.second[1] == bestFreq && entry.second[2] < bestTime)) {
                    bestFreq = entry.second[1]; bestTime = entry.second[2]; evictKey = entry.first;
                }
            }
            cache.erase(evictKey);
        }
        clock++;
        cache[key] = {value, 1, clock};
    }
};

