import java.util.*;

public class Main {
    class LFUCache {
        int capacity, minFreq = 0;
        Map<Integer, Integer> keyValue = new HashMap<>();
        Map<Integer, Integer> keyFreq = new HashMap<>();
        Map<Integer, LinkedHashSet<Integer>> freqKeys = new HashMap<>();     // frequency to ordered keys, oldest first

        public LFUCache(int capacity) {
            this.capacity = capacity;
        }

        void touch(int key) {
            int freq = keyFreq.get(key);
            freqKeys.get(freq).remove(key);                                    // remove from its current frequency group
            if (freqKeys.get(freq).isEmpty() && freq == minFreq) minFreq++;       // that group is now empty
            keyFreq.put(key, freq + 1);
            freqKeys.computeIfAbsent(freq + 1, k -> new LinkedHashSet<>()).add(key); // re-insert into the next group
        }

        public int get(int key) {
            if (!keyValue.containsKey(key)) return -1;
            touch(key);
            return keyValue.get(key);
        }

        public void put(int key, int value) {
            if (capacity == 0) return;
            if (keyValue.containsKey(key)) {
                keyValue.put(key, value);
                touch(key);
                return;
            }
            if (keyValue.size() >= capacity) {
                int oldestKey = freqKeys.get(minFreq).iterator().next();            // least recently used at minFreq
                freqKeys.get(minFreq).remove(oldestKey);
                keyValue.remove(oldestKey);
                keyFreq.remove(oldestKey);
            }
            keyValue.put(key, value);
            keyFreq.put(key, 1);
            freqKeys.computeIfAbsent(1, k -> new LinkedHashSet<>()).add(key);
            minFreq = 1;
        }
    }

    public static void main(String[] args) {
        LFUCache cache = new LFUCache(2);
        cache.put(1, 1);
        cache.put(2, 2);
        System.out.println(cache.get(1));
        cache.put(3, 3);
        System.out.println(cache.get(2));
        System.out.println(cache.get(3));
        cache.put(4, 4);
    }
}

