#include <bits/stdc++.h>
using namespace std;

class LFUCache {
public:
    int capacity, minFreq = 0;
    unordered_map<int, int> keyValue, keyFreq;
    unordered_map<int, list<int>> freqKeys;                              // frequency to keys, oldest at the front
    unordered_map<int, list<int>::iterator> keyIter;                       // key to its position within its group

    LFUCache(int capacity) : capacity(capacity) {}

    void touchKey(int key) {
        int freq = keyFreq[key];
        freqKeys[freq].erase(keyIter[key]);                                    // remove from its current frequency group
        if (freqKeys[freq].empty() && freq == minFreq) minFreq++;                // that group is now empty
        keyFreq[key] = freq + 1;
        freqKeys[freq + 1].push_back(key);                                        // re-insert into the next group
        keyIter[key] = prev(freqKeys[freq + 1].end());
    }

    int get(int key) {
        if (!keyValue.count(key)) return -1;
        touchKey(key);
        return keyValue[key];
    }

    void put(int key, int value) {
        if (capacity == 0) return;
        if (keyValue.count(key)) {
            keyValue[key] = value;
            touchKey(key);
            return;
        }
        if ((int)keyValue.size() >= capacity) {
            int oldestKey = freqKeys[minFreq].front();                               // least recently used at minFreq
            freqKeys[minFreq].pop_front();
            keyValue.erase(oldestKey);
            keyFreq.erase(oldestKey);
            keyIter.erase(oldestKey);
        }
        keyValue[key] = value;
        keyFreq[key] = 1;
        freqKeys[1].push_back(key);
        keyIter[key] = prev(freqKeys[1].end());
        minFreq = 1;
    }
};

int main() {
    LFUCache cache(2);
    cache.put(1, 1);
    cache.put(2, 2);
    cout << cache.get(1) << endl;
    cache.put(3, 3);
    cout << cache.get(2) << endl;
    cout << cache.get(3) << endl;
    cache.put(4, 4);
    return 0;
}
